#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    // Expect A.size() == N*N; if not, compute over the available range safely.
    const size_t total = A.size();
    const size_t rows = (N == 0) ? 0 : std::min(N, total / N);

    int globalMax = 0;

    #pragma omp parallel
    {
        int localMax = 0;

        #pragma omp for nowait
        for (size_t i = 0; i < rows; ++i) {
            int deg = 0;
            const size_t rowStart = i * N;

            // Sum row i (safe even if A is shorter than N*N)
            const size_t cols = std::min(N, total - rowStart);
            for (size_t j = 0; j < cols; ++j) {
                deg += A[rowStart + j];
            }

            if (deg > localMax) localMax = deg;
        }

        #pragma omp critical
        {
            if (localMax > globalMax) globalMax = localMax;
        }
    }

    return globalMax;
}
